// ── Program.cs — Registration Order Matters! ──
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

var app = builder.Build();

// 1. Exception handling (outermost — catches everything)
app.UseExceptionHandler("/error");

// 2. HTTPS redirect
app.UseHttpsRedirection();

// 3. Static files (short-circuits if file found)
app.UseStaticFiles();

// 4. Routing (matches URL to endpoint)
app.UseRouting();

// 5. Auth (must be after routing, before endpoints)
app.UseAuthentication();
app.UseAuthorization();

// 6. Endpoints
app.MapControllers();

app.Run();

// ── Custom Middleware ──
public class RequestTimingMiddleware {
    private readonly RequestDelegate _next;
    private readonly ILogger _logger;

    public RequestTimingMiddleware(RequestDelegate next, ILogger<RequestTimingMiddleware> logger) {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context) {
        var sw = Stopwatch.StartNew();  // BEFORE next()

        await _next(context);            // Pass to next middleware

        sw.Stop();                       // AFTER next() — response phase
        _logger.LogInformation($"{context.Request.Path} took {sw.ElapsedMilliseconds}ms");
    }
}

// Register: app.UseMiddleware<RequestTimingMiddleware>();
